require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_role('customer');
$id=(int)($_GET['id']??0);$stmt=$pdo->prepare("SELECT b.*,p.name package_name,p.category,u.name customer_name,u.phone FROM bookings b JOIN packages p ON p.id=b.package_id JOIN users u ON u.id=b.user_id WHERE b.id=? AND b.user_id=?");$stmt->execute([$id,current_user()['id']]);$order=$stmt->fetch();if(!$order){flash('danger','Pesanan tidak ditemukan.');redirect('customer/orders.php');}
$stmt=$pdo->prepare("SELECT * FROM payments WHERE booking_id=? ORDER BY id DESC");$stmt->execute([$id]);$payments=$stmt->fetchAll();
$pageTitle='Detail Pesanan';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/customer_nav.php';
?>
<section class="section" style="padding-top:30px"><div class="container"><div class="dashboard-head"><div><h1><?= e($order['booking_code']) ?></h1><p>Detail pesanan dan status pembayaran.</p></div><a class="btn btn-outline" href="<?= url('customer/orders.php') ?>">← Kembali</a></div><div class="detail-grid"><div><div class="panel"><div class="panel-head"><h2>Informasi Pesanan</h2><span class="badge badge-<?= status_class($order['status']) ?>"><?= e(booking_status_label($order['status'])) ?></span></div><div class="panel-body"><dl class="detail-list"><dt>Paket</dt><dd><?= e($order['package_name']) ?> (<?= e($order['category']) ?>)</dd><dt>Tanggal dan waktu</dt><dd><?= date('d F Y',strtotime($order['event_date'])) ?>, <?= substr($order['start_time'],0,5) ?> WIB</dd><dt>Lokasi</dt><dd><?= e($order['location']) ?></dd><dt>Total harga</dt><dd><?= rupiah($order['total_price']) ?></dd><dt>DP minimal</dt><dd><?= rupiah($order['dp_amount']) ?></dd><dt>Catatan</dt><dd><?= nl2br(e($order['notes'] ?: '-')) ?></dd><dt>Catatan admin</dt><dd><?= nl2br(e($order['admin_note'] ?: '-')) ?></dd></dl></div></div><div class="panel"><div class="panel-head"><h2>Riwayat Pembayaran</h2><?php if(in_array($order['status'],['awaiting_payment','payment_review'],true)): ?><a class="btn btn-primary btn-sm" href="<?= url('customer/payment_upload.php?booking='.$order['id']) ?>">Unggah Bukti</a><?php endif; ?></div><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Jumlah</th><th>Bank</th><th>Status</th><th>Bukti</th></tr></thead><tbody><?php if(!$payments): ?><tr><td colspan="5" class="empty">Belum ada pembayaran.</td></tr><?php else: foreach($payments as $pay): ?><tr><td><?= date('d-m-Y',strtotime($pay['payment_date'])) ?></td><td><?= rupiah($pay['amount']) ?></td><td><?= e($pay['bank_name']) ?><br><small><?= e($pay['account_name']) ?></small></td><td><span class="badge badge-<?= status_class($pay['verification_status']) ?>"><?= e(payment_status_label($pay['verification_status'])) ?></span><?php if($pay['admin_note']): ?><br><small><?= e($pay['admin_note']) ?></small><?php endif; ?></td><td><a class="btn btn-outline btn-sm" target="_blank" href="<?= url('uploads/payments/'.$pay['proof']) ?>">Lihat</a></td></tr><?php endforeach; endif; ?></tbody></table></div></div></div><aside><div class="panel"><div class="panel-head"><h3>Alur Status</h3></div><div class="panel-body order-timeline"><div class="timeline-item"><span class="timeline-dot"></span><div><strong>Pesanan dibuat</strong><br><small><?= date('d-m-Y H:i',strtotime($order['created_at'])) ?></small></div></div><div class="timeline-item"><span class="timeline-dot"></span><div><strong>Pembayaran DP</strong><br><small>Unggah bukti pembayaran minimal <?= rupiah($order['dp_amount']) ?>.</small></div></div><div class="timeline-item"><span class="timeline-dot"></span><div><strong>Verifikasi admin</strong><br><small>Pesanan masuk ke jadwal setelah pembayaran diterima.</small></div></div><div class="timeline-item"><span class="timeline-dot"></span><div><strong>Pelaksanaan</strong><br><small>Tim hadir sesuai tanggal dan lokasi yang disepakati.</small></div></div></div></div></aside></div></div></section>
